    @property
    def last_finalized(self):
        return self.record.get("lastFinalized")

    def raise_for_status(self):
        if not self.finalized:
            raise NativeError(self.record.get("runtimeError") or self.result.get("reason") or
                              "ORIGINAL_ACCOUNTING_NOT_FINALIZED",
                              returncode=self.record.get("returncode"))
        return self


@dataclass(frozen=True)
class SessionAccountingResult:
    """One native page/chunk accounting range. The original ledger owns finality.

    Amounts and completion describe this range only. A retained prior receipt
    remains visible in an entry's lastFinalized after a later source failure.
    """
    native: dict
    returncode: int = 0
    runtime_error: str | None = None
    interrupted: bool = False

    @classmethod
    def from_native(cls, native, *, kind, directory, returncode=0,
                    runtime_error=None, interrupted=False):
        if (not isinstance(native, dict)
                or native.get("schema") != "stellar-forge.sf88.session-accounting.v1"
                or native.get("kind") != kind or native.get("directory") != str(directory)
                or not isinstance(native.get("sessionId"), str)
                or not isinstance(native.get("configurationSha256"), str)
                or not re.fullmatch(r"[a-f0-9]{64}", native.get("configurationSha256", ""))
                or native.get("mode") not in ("VIEW", "FINALIZE")
                or not isinstance(native.get("range"), dict)
                or not isinstance(native.get("entries"), list)):
            raise StateError("ORIGINAL_SESSION_ACCOUNTING_RESULT_INVALID")
        window, entries = native["range"], native["entries"]
        if (any(type(window.get(key)) is not int for key in ("offset", "limit", "total"))
                or not 0 <= window["offset"] <= window["total"]
                or not 1 <= window["limit"] <= 250
                or len(entries) > min(window["limit"], window["total"] - window["offset"])):
            raise StateError("ORIGINAL_SESSION_ACCOUNTING_RANGE_INVALID")
        next_offset = window["offset"] + len(entries)
        if not entries and next_offset < window["total"] and not native.get("interrupted"):
            raise StateError("ORIGINAL_SESSION_ACCOUNTING_RANGE_INVALID")
        if window.get("nextOffset") != (next_offset if next_offset < window["total"] else None):
            raise StateError("ORIGINAL_SESSION_ACCOUNTING_RANGE_INVALID")
        for position, entry in enumerate(entries):
            if (not isinstance(entry, dict)
                    or entry.get("index") != window["offset"] + position + (kind == "dataset")
                    or not isinstance(entry.get("outcome"), str)):
                raise StateError("ORIGINAL_SESSION_ACCOUNTING_ENTRY_INVALID")
            if entry["outcome"] in ("FINALIZED", "IDEMPOTENT_FINALIZED") and (
                    not isinstance(entry.get("actualAtomicUnits"), str)
                    or not re.fullmatch(r"[0-9]+", entry["actualAtomicUnits"])
                    or not isinstance(entry.get("receipt"), str)):
                raise StateError("ORIGINAL_SESSION_ACCOUNTING_RECEIPT_INVALID")
        return cls(deepcopy(native), returncode, runtime_error,
                   interrupted or native.get("interrupted") is True)

    @property
    def entries(self):
        return deepcopy(self.native["entries"])

    @property
    def next_offset(self):
        return self.native["range"]["nextOffset"]

    @property
    def attention(self):
        return [entry for entry in self.entries if entry["outcome"] not in
                ("FINALIZED", "IDEMPOTENT_FINALIZED", "NO_PAYMENT_REQUIRED", "NOT_ATTEMPTED")
                or entry.get("viewStatus") == "SAVE_FAILED"]

    @property
    def window_complete(self):
        return self.returncode in (0, 2) and not self.interrupted and not self.runtime_error and not self.attention

    @property
    def recorded_actual_atomic_units(self):
        """Sum only current finalized native amounts in this displayed range."""
        return str(sum(int(entry["actualAtomicUnits"]) for entry in self.native["entries"]
                       if entry["outcome"] in ("FINALIZED", "IDEMPOTENT_FINALIZED")))

    def raise_for_status(self):
        if not self.window_complete:
            raise NativeError(self.runtime_error or "ORIGINAL_SESSION_ACCOUNTING_NEEDS_ATTENTION",
                              returncode=self.returncode)
        return self

"""Bounded subprocess calls to the existing SF88 CLI, with native cancellation."""
from __future__ import annotations

from dataclasses import dataclass
import os
from pathlib import Path
import re
import selectors
import shutil
import signal
import subprocess
import time
import threading

from .errors import NativeError, StateError
from .storage import parse

CLI = Path("stellar/scf-starforge-20261009/sf88-operator-buyer-cli/cli.mjs")
BRIDGE = CLI.parent / "python" / "bridge.mjs"
DATASET_BRIDGE = CLI.parent / "python" / "dataset-bridge.mjs"
APPLICATIONS = {
    "application": BRIDGE,
    "consumer": CLI.parent / "python" / "consumer-bridge.mjs",
    "research": CLI.parent / "python" / "research-bridge.mjs",
    "dataset": DATASET_BRIDGE,
    "dbnomics": CLI.parent.parent / "sf30-seller-sdk" / "dbnomics" / "cli.mjs",
    "finalized-dataset": CLI.parent / "python" / "finalized-dataset-bridge.mjs",
    "object": CLI.parent / "python" / "object-bridge.mjs",
    "acquisitions": CLI.parent.parent / "buyer-runbook" / "customer-bridge.mjs",
}


@dataclass(frozen=True)
class Run:
    returncode: int
    output: dict | None
    error: str | None
    interrupted: bool = False


class Runtime:
    def __init__(self, checkout, *, node="node", environment=None, timeout=360, output_limit=2_097_152):
        self.checkout = Path(checkout).expanduser().resolve()
        self.cli = self.checkout / CLI
        self.node = shutil.which(os.fspath(node))
        if not self.node or not self.cli.is_file():
            raise StateError("ORIGINAL_NODE_RUNTIME_REQUIRED")
        if not 1 <= timeout <= 3600 or not 8192 <= output_limit <= 16_777_216:
            raise StateError("RUNTIME_LIMIT_INVALID")
        self.environment = None if environment is None else dict(environment)
        self.timeout = timeout
        self.output_limit = output_limit

    def run(self, arguments, *, logs: Path | None = None, started=None, target="buyer", cancel_event=None) -> Run:
        if cancel_event is not None and not isinstance(cancel_event, threading.Event):
            raise StateError("NATIVE_CANCEL_EVENT_INVALID")
        if cancel_event is not None and cancel_event.is_set():
            raise StateError("NATIVE_CANCELLED_BEFORE_START")
        if target != "buyer" and target not in APPLICATIONS:
            raise StateError("ORIGINAL_RUNTIME_TARGET_INVALID")
        entry = self.cli if target == "buyer" else self.checkout / APPLICATIONS[target]
        if not entry.is_file():
            raise StateError("ORIGINAL_APPLICATION_RUNTIME_REQUIRED")
        # Keep the controlling terminal. SF81/SF62 opens /dev/tty itself; this
        # wrapper never synthesizes answers or replaces the native approval.
        stdout = bytearray()
        stderr = bytearray()
        process = None
        selector = selectors.DefaultSelector()
        log_files = {}
        interruption = None
        deadline = time.monotonic() + self.timeout
        kill_at = None
        try:
            if logs:
                for name in ("stdout", "stderr"):
                    fd = os.open(logs / (name + ".json"), os.O_WRONLY | os.O_CREAT | os.O_EXCL, 0o600)
                    log_files[name] = os.fdopen(fd, "wb", buffering=0)
            try:
                process = subprocess.Popen([self.node, str(entry), *map(str, arguments)],
                    cwd=self.checkout, env=self.environment, shell=False,
                    stdin=subprocess.DEVNULL, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
            except OSError:
                raise NativeError("NATIVE_PROCESS_START_FAILED") from None
            if started:
                started(process.pid)
            for stream, name in ((process.stdout, "stdout"), (process.stderr, "stderr")):
                os.set_blocking(stream.fileno(), False)
                selector.register(stream, selectors.EVENT_READ, name)
            while selector.get_map() or process.poll() is None:
                try:
                    now = time.monotonic()
                    if cancel_event is not None and cancel_event.is_set() and interruption is None:
                        interruption = "NATIVE_CANCELLED"
                    if now >= deadline and interruption is None:
                        interruption = "NATIVE_TIMEOUT"
                    if interruption and kill_at is None:
                        if process.poll() is None:
                            process.send_signal(signal.SIGTERM)
                        kill_at = now + 15
                    if kill_at is not None and now >= kill_at:
                        if process.poll() is None:
                            process.kill()
                        # Descendants cannot keep an abandoned output pipe open.
                        for key in list(selector.get_map().values()):
                            selector.unregister(key.fileobj)
                            key.fileobj.close()
                        break
                    for key, _ in selector.select(0.1):
                        chunk = os.read(key.fd, 65536)
                        if not chunk:
                            selector.unregister(key.fileobj)
                            key.fileobj.close()
                            continue
                        target = stdout if key.data == "stdout" else stderr
                        left = self.output_limit - len(target)
                        target.extend(chunk[:max(0, left)])
                        if logs and left > 0:
                            log_files[key.data].write(chunk[:left])
                        if len(chunk) > left:
                            interruption = "NATIVE_OUTPUT_LIMIT"
                except KeyboardInterrupt:
                    interruption = "NATIVE_INTERRUPTED"
            code = process.wait(timeout=5)
            output = self._object(stdout)
            error_record = self._object(stderr)
            error = error_record.get("error") if error_record else None
            if not isinstance(error, str) or not re.fullmatch(r"[A-Z0-9_]{1,120}", error):
                error = None
            if output is None and not error:
                error = "NATIVE_RESULT_INVALID"
            return Run(code, output, interruption or error, interruption is not None)
        finally:
            selector.close()
            if process:
                if process.poll() is None:
                    process.terminate()
                    try:
                        process.wait(timeout=15)
                    except subprocess.TimeoutExpired:
                        process.kill()
                        process.wait()
                for stream in (process.stdout, process.stderr):
                    if stream and not stream.closed:
                        stream.close()
            for stream in log_files.values():
                os.fsync(stream.fileno())
                stream.close()

    @staticmethod
    def _object(raw):
        try:
            value = parse(bytes(raw))
            return value if isinstance(value, dict) else None
        except StateError:
            return None

    def checked(self, arguments, *, mode: str, target="buyer") -> dict:
        result = self.run(arguments, target=target)
        if result.returncode or result.error or result.output is None or result.output.get("mode") != mode:
            raise NativeError(result.error or "NATIVE_COMMAND_FAILED", returncode=result.returncode)
        return result.output

"""Spatial commands on the original stellar-forge-duckdb entrypoint."""
from __future__ import annotations

from pathlib import Path
from .duckdb_spatial import DuckDBSpatial
from .storage import parse,read


def add_parser(commands):
    parser = commands.add_parser("spatial",help="Review original GIS layers, query and exchange native GIS files")
    sub = parser.add_subparsers(dest="spatial_command",required=True)
    sub.add_parser("status",help="Reopen GIS layers, layer bindings and saved queries")
    sub.add_parser("runtime",help="Load the installed signed spatial extension and read actual GDAL drivers")
    review = sub.add_parser("review",help="Review exact geometry and CRS from an immutable dataset edition")
    review.add_argument("edition_id")
    review.add_argument("--geometry-column",required=True)
    review.add_argument("--format",dest="source_format",choices=["esri-json","geojson","wkt","wkb-hex"],required=True)
    review.add_argument("--crs",required=True,help="Native source CRS, for example EPSG:3857")
    review.add_argument("--spatial-reference-column")
    review.add_argument("--geometry-type",choices=["esriGeometryPoint","esriGeometryMultipoint","esriGeometryPolyline","esriGeometryPolygon"])
    review.add_argument("--geometry-name",default="geometry")
    review.add_argument("--keys",help="Comma-separated original SQL key columns; defaults to the edition keys")
    adopt = sub.add_parser("adopt",help="Retain the reviewed source as an immutable GIS layer")
    adopt.add_argument("review_id")
    active = sub.add_parser("activate",help="Select a layer through a revisioned spatial SQL alias")
    active.add_argument("name")
    active.add_argument("layer_id")
    active.add_argument("--expected-revision",type=int,required=True)
    preview = sub.add_parser("preview",help="Return exact original geometry for the native-CRS map")
    preview.add_argument("layer_id")
    preview.add_argument("--max-rows",type=int,default=100)
    for name in ("query","save-query"):
        p = sub.add_parser(name,help="Preview or retain read-only native spatial SQL")
        if name=="save-query":
            p.add_argument("name")
            p.add_argument("--expected-revision",type=int,default=0)
        else:
            p.add_argument("--max-rows",type=int,default=200)
            p.add_argument("--expected-bindings",help="Exact JSON bindings returned by a spatial preview")
        source = p.add_mutually_exclusive_group(required=True)
        source.add_argument("--sql")
        source.add_argument("--sql-file")
        p.add_argument("--parameters",default="[]")
    export = sub.add_parser("export",help="Retain the complete query as GeoPackage and GeoParquet plus original source")
    export.add_argument("query_id")
    export.add_argument("--destination",required=True)
    export.add_argument("--expected-revision",type=int,required=True)
    export.add_argument("--geometry-column",default="geometry")
    export.add_argument("--target-crs",help="Native reprojection before export; omission retains the query CRS")
    export.add_argument("--expected-bindings")
    receive = sub.add_parser("receive",help="Independently reopen exported GIS files and compare all attributes and geometry")
    receive.add_argument("directory")
    return parser


def dispatch(workspace,args):
    gis = DuckDBSpatial(workspace,extension_path=args.spatial_extension)
    command = args.spatial_command
    if command=="status": return gis.status()
    if command=="runtime": return gis.runtime()
    if command=="review":
        return gis.review_layer(args.edition_id,geometry_column=args.geometry_column,source_format=args.source_format,
            crs=args.crs,spatial_reference_column=args.spatial_reference_column,geometry_type=args.geometry_type,
            geometry_name=args.geometry_name,keys=[k.strip() for k in args.keys.split(",") if k.strip()] if args.keys is not None else None)
    if command=="adopt": return gis.adopt_layer(args.review_id)
    if command=="activate": return gis.activate(args.name,args.layer_id,expected_revision=args.expected_revision)
    if command=="preview": return gis.preview(args.layer_id,max_rows=args.max_rows)
    if command in {"query","save-query"}:
        sql = args.sql if args.sql is not None else read(Path(args.sql_file),262144).decode()
        parameters = parse(args.parameters.encode())
        if command=="save-query": return gis.save_query(args.name,sql,parameters,expected_revision=args.expected_revision)
        return gis.query(sql,parameters,max_rows=args.max_rows,
                         expected_bindings=parse(args.expected_bindings.encode()) if args.expected_bindings else None)
    if command=="export":
        return gis.export_query(args.query_id,args.destination,expected_revision=args.expected_revision,
            geometry_column=args.geometry_column,target_crs=args.target_crs,
            expected_bindings=parse(args.expected_bindings.encode()) if args.expected_bindings else None)
    if command=="receive": return gis.receive_files(args.directory)
    raise ValueError("Unknown spatial command")

"""GIS routes carried by the original private DuckDB operator."""
from __future__ import annotations

from .duckdb_spatial import DuckDBSpatial
from .errors import StateError


def spatial(operator):
    if not hasattr(operator,"_spatial"):
        operator._spatial = DuckDBSpatial(operator.workspace,extension_path=operator.spatial_extension)
    return operator._spatial


def get(operator,path):
    from .duckdb_http import _identifier
    parts = path.strip("/").split("/")
    gis = spatial(operator)
    if path=="/api/spatial/state": return gis.status()
    if len(parts)==4 and parts[2] in {"layers","reviews","queries"}:
        identity = _identifier(parts[3])
        key = {"layers":"layer_id","reviews":"review_id","queries":"query_id"}[parts[2]]
        record = next((r for r in gis.status()[parts[2]] if r[key]==identity),None)
        if record is not None: return record
    raise StateError("DUCKDB_SPATIAL_ROUTE_NOT_FOUND")


def validate_export(body):
    from .duckdb_http import _fields,_identifier,_integer
    _fields(body,("query_id","expected_revision","request_id"),("geometry_column","target_crs","expected_bindings"))
    _identifier(body["query_id"])
    _integer(body["expected_revision"],"revision",1)


def export(operator,body,destination):
    return spatial(operator).export_query(body["query_id"],destination,expected_revision=body["expected_revision"],
        geometry_column=body.get("geometry_column","geometry"),target_crs=body.get("target_crs"),
        expected_bindings=body.get("expected_bindings"))


def perform(operator,path,body):
    from .duckdb_http import _fields,_integer
    gis = spatial(operator)
    if path=="/api/spatial/runtime":
        _fields(body)
        return gis.runtime()
    if path=="/api/spatial/reviews":
        _fields(body,("edition_id","geometry_column","source_format","crs"),
                ("spatial_reference_column","geometry_type","keys","geometry_name"))
        return gis.review_layer(**body)
    if path=="/api/spatial/adopt":
        _fields(body,("review_id",))
        return gis.adopt_layer(body["review_id"])
    if path=="/api/spatial/activate":
        _fields(body,("name","layer_id","expected_revision"))
        return gis.activate(body["name"],body["layer_id"],expected_revision=_integer(body["expected_revision"],"revision"))
    if path=="/api/spatial/preview":
        _fields(body,("layer_id",),("max_rows",))
        return gis.preview(body["layer_id"],max_rows=_integer(body.get("max_rows",100),"max_rows",1,1000))
    if path=="/api/spatial/query":
        _fields(body,("sql",),("parameters","max_rows","expected_bindings"))
        return gis.query(body["sql"],body.get("parameters",[]),max_rows=_integer(body.get("max_rows",200),"max_rows",1,10000),
                         expected_bindings=body.get("expected_bindings"))
    if path=="/api/spatial/queries":
        _fields(body,("name","sql"),("parameters","expected_revision"))
        return gis.save_query(body["name"],body["sql"],body.get("parameters",[]),
                              expected_revision=_integer(body.get("expected_revision",0),"revision"))
    if path=="/api/spatial/exports":
        return operator._retained_action(path,body)
    raise StateError("DUCKDB_SPATIAL_ROUTE_NOT_FOUND")

"""Use original acquired datasets in a durable, local SQLite application."""
from __future__ import annotations

from contextlib import contextmanager
from dataclasses import dataclass
from datetime import datetime, timezone
import hashlib
import json
import math
import os
from pathlib import Path
import re
import sqlite3
import stat
import tempfile
import time

from .datasets import DatasetDelivery
from .dataset_semantics import read_delivery_semantics, sql_descriptor, sql_context
from .errors import StateError
from .storage import digest, parse, private_directory, sync_directory

_APPLICATION = 0x53464442
_FORMAT = "stellar-forge.python-dataset-sqlite.v1"
_HEX = re.compile(r"[a-f0-9]{64}")
_ORDINAL = "_sf_row_number"
_META = "sf_dataset_versions"
_HEADS = "sf_dataset_views"
_HISTORY = "sf_dataset_activations"
_SEMANTICS = "sf_dataset_semantics"


def _json(value):
    return json.dumps(value, ensure_ascii=False, allow_nan=False, sort_keys=True, separators=(",", ":"))


def _identifier(value):
    if not isinstance(value, str) or not value or len(value.encode("utf-8")) > 512 or any(ord(c) < 32 for c in value):
        raise StateError("DATASET_SQL_IDENTIFIER_INVALID")
    return '"' + value.replace('"', '""') + '"'


def _view_name(value):
    if not isinstance(value, str) or not re.fullmatch(r"[a-zA-Z][a-zA-Z0-9_]{0,63}", value) or value.lower().startswith(("sqlite_", "sf_dataset_")):
        raise StateError("DATASET_SQL_VIEW_NAME_INVALID")
    return value


def _scalar(value):
    if value is None:
        return value, "null"
    if type(value) is bool:
        return int(value), "boolean"
    if type(value) is int and -(2**63) <= value < 2**63:
        return value, "integer"
    if type(value) is float and math.isfinite(value):
        return value, "number"
    if isinstance(value, str):
        value.encode("utf-8")
        return value, "string"
    raise StateError("DATASET_SQL_VALUE_NOT_REPRESENTABLE")


@dataclass(frozen=True)
class QueryResult:
    columns: tuple[str, ...]
    rows: tuple[tuple, ...]
    truncated: bool
    views: tuple[dict, ...] = ()
    read_tables: tuple[str, ...] = ()

    def dictionaries(self):
        if len(set(self.columns)) != len(self.columns):
            raise StateError("DATASET_SQL_DUPLICATE_RESULT_NAMES_USE_ALIASES")
        return [dict(zip(self.columns, row)) for row in self.rows]


class DatasetDatabase:
    """A private customer database; acquisition and payment remain in SF88.

    Imports retain independent immutable tables. Named SQL views select a
    version only through activate(), using its current revision. A standard
    SQLite client can read the resulting database without this Python package.
    """

    def __init__(self, directory, *, create=True, busy_timeout=30):
        if not isinstance(busy_timeout, (int, float)) or not math.isfinite(busy_timeout) or not 0 < busy_timeout <= 300:
            raise StateError("DATASET_SQL_BUSY_TIMEOUT_INVALID")
        self.directory = private_directory(Path(directory), create=create)
        self.path = self.directory / "datasets.sqlite3"
        self.busy_timeout = busy_timeout
        if create:
            try:
                fd = os.open(self.path, os.O_CREAT | os.O_EXCL | os.O_RDWR | os.O_NOFOLLOW, 0o600)
            except FileExistsError:
                pass
            else:
                os.close(fd)
                sync_directory(self.directory)
        self._check_file()
        with self._connection(readonly=not create) as db:
            db.execute("BEGIN IMMEDIATE" if create else "BEGIN")
            try:
                application = db.execute("PRAGMA application_id").fetchone()[0]
                version = db.execute("PRAGMA user_version").fetchone()[0]
                objects = db.execute("SELECT name FROM sqlite_master LIMIT 1").fetchone()
                if create and not application and not version and not objects:
                    db.execute(f"CREATE TABLE {_META}(sequence INTEGER PRIMARY KEY,version_id TEXT UNIQUE NOT NULL,created_at TEXT NOT NULL,record TEXT NOT NULL,manifest BLOB NOT NULL)")
                    db.execute(f"CREATE TABLE {_HEADS}(name TEXT PRIMARY KEY COLLATE NOCASE,version_id TEXT NOT NULL REFERENCES {_META}(version_id),revision INTEGER NOT NULL CHECK(revision>0))")
                    db.execute(f"CREATE TABLE {_HISTORY}(sequence INTEGER PRIMARY KEY,name TEXT NOT NULL,version_id TEXT NOT NULL REFERENCES {_META}(version_id),previous_version TEXT,revision INTEGER NOT NULL,activated_at TEXT NOT NULL)")
                    db.execute(f"PRAGMA application_id={_APPLICATION}")
                    db.execute("PRAGMA user_version=1")
                elif application != _APPLICATION or version != 1:
                    raise StateError("DATASET_SQL_DATABASE_FORMAT_MISMATCH")
                if create:
                    # Additive storage belongs to the same immutable edition and
                    # travels in the original SQLite backup/portable workspace.
                    db.execute(f"CREATE TABLE IF NOT EXISTS {_SEMANTICS}(version_id TEXT PRIMARY KEY REFERENCES {_META}(version_id),document BLOB NOT NULL)")
                db.commit()
            except BaseException:
                db.rollback()
                raise

    def _check_file(self):
        if private_directory(self.directory, create=False) != self.directory:
            raise StateError("DATASET_SQL_DIRECTORY_CHANGED")
        try:
            fd = os.open(self.path, os.O_RDONLY | os.O_NOFOLLOW)
            try:
                info = os.fstat(fd)
                if not stat.S_ISREG(info.st_mode) or info.st_nlink != 1 or info.st_mode & 0o077:
                    raise StateError("DATASET_SQL_PRIVATE_FILE_REQUIRED")
            finally:
                os.close(fd)
        except OSError:
            raise StateError("DATASET_SQL_FILE_UNAVAILABLE") from None

    @contextmanager
    def _connection(self, *, readonly=False):
        self._check_file()
        db = sqlite3.connect(self.path.as_uri() + ("?mode=ro" if readonly else "?mode=rw"), uri=True,
                             isolation_level=None, timeout=self.busy_timeout)
        try:
            db.row_factory = sqlite3.Row
            db.execute("PRAGMA foreign_keys=ON")
            db.execute("PRAGMA trusted_schema=OFF")
            if readonly:
                db.execute("PRAGMA query_only=ON")
            else:
                db.execute("PRAGMA synchronous=FULL")
            yield db
        finally:
            db.close()

    @staticmethod
    def _version(db, version_id):
        row = db.execute(f"SELECT sequence,record FROM {_META} WHERE version_id=?", (version_id,)).fetchone()
        if row is None:
            raise StateError("DATASET_SQL_VERSION_NOT_FOUND")
        record = {**parse(row["record"].encode()), "sequence": row["sequence"]}
        if record.get("semantics") is not None:
            retained = db.execute(f"SELECT document FROM {_SEMANTICS} WHERE version_id=?", (version_id,)).fetchone()
            if retained is None:
                raise StateError("DATASET_SQL_SEMANTIC_DOCUMENT_MISSING")
            context = sql_context(bytes(retained["document"]), record["semantics"], version_id)
            record["semantic_dictionary"] = context["document"]
        return record

    def import_delivery(self, delivery: DatasetDelivery, *, columns=None):
        """Commit the verified complete room once; do not change any named view.

        columns optionally maps original field names to SQLite column names.
        Values keep their native JSON scalar types; SQLite stores booleans as
        integers and this record retains each column's observed JSON types.
        """
        if not isinstance(delivery, DatasetDelivery):
            raise StateError("DATASET_SQL_ORIGINAL_DELIVERY_REQUIRED")
        native = delivery.native
        status = native.get("nativeStatus") or {}
        binding = native.get("sourceBindingSha256")
        if native.get("schema") not in {"stellar-forge.sf88.dataset-delivery.v1", "stellar-forge.sf100.dataset-delivery.v1"} or not isinstance(binding, str) or not _HEX.fullmatch(binding) or status.get("complete") is not True or status.get("finalized") is not True:
            raise StateError("DATASET_SQL_COMPLETE_NATIVE_DELIVERY_REQUIRED")
        manifest_bytes = delivery.file("manifest.json").read_bytes(limit=4 * 1024 * 1024)
        manifest_sha = digest(manifest_bytes)
        if manifest_sha != native["outputs"]["manifest.json"]["sha256"]:
            raise StateError("DATASET_SQL_MANIFEST_CHANGED")
        manifest = parse(manifest_bytes)
        dataset = manifest.get("dataset") or {}
        fields = dataset.get("projectedFields")
        total = dataset.get("rows")
        source_pages = manifest.get("sourcePages")
        if manifest.get("schema") != "stellar-forge.buyer-delivery-manifest.v1" or not isinstance(fields, list) or not fields or len(fields) > 1024 or not all(isinstance(field, str) for field in fields) or len(set(fields)) != len(fields) or type(total) is not int or not 0 <= total <= 1_000_000 or status.get("rows") != total or status.get("snapshot") != dataset.get("snapshot") or not isinstance(source_pages, list) or status.get("pages") != len(source_pages) or manifest.get("paymentStatus") != native.get("paymentStatus"):
            raise StateError("DATASET_SQL_MANIFEST_BINDING_INVALID")
        columns = {} if columns is None else columns
        if not isinstance(columns, dict) or set(columns) - set(fields):
            raise StateError("DATASET_SQL_COLUMN_MAPPING_INVALID")
        mapped = [columns.get(field, field) for field in fields]
        quoted = [_identifier(column) for column in mapped]
        folded = [column.lower() for column in mapped]
        if len(set(folded)) != len(folded) or _ORDINAL in folded:
            raise StateError("DATASET_SQL_COLUMN_COLLISION_USE_MAPPING")
        source = native["outputs"]["dataset.jsonl"]
        if manifest.get("outputs", {}).get("dataset.jsonl") != {key: source[key] for key in ("bytes", "sha256")}:
            raise StateError("DATASET_SQL_ROW_BINDING_INVALID")
        semantics = read_delivery_semantics(delivery, manifest=manifest)
        semantic_mapping = sql_descriptor(semantics, fields, mapped) if semantics else None
        identity = {"schema": _FORMAT, "manifestSha256": manifest_sha, "sourceBindingSha256": binding,
                    "columns": list(zip(fields, mapped))}
        return self._import_rows(manifest_bytes=manifest_bytes, identity=identity, fields=fields,
            mapped=mapped, total=total, source=source, opener=delivery.file("dataset.jsonl").open,
            semantics=semantics,
            details={"dataset": dataset, "sourceDirectory": native.get("sourceDirectory"),
                     "source_pages": len(source_pages), "originalPaymentStatus": native.get("paymentStatus"),
                     **({"semantics": semantic_mapping} if semantic_mapping else {})})

    def import_response(self, projection, *, allow_incomplete=False):
        """Commit a complete analytical projection with its distinct source manifest.

        This consumes retained response records only. It neither fabricates an
        SF100 delivery nor changes the original source's payment/completion state.
        """
        from .response_tables import ResponseProjection, SCHEMA
        if not isinstance(projection, ResponseProjection) or projection.manifest.get("schema") != SCHEMA:
            raise StateError("DATASET_SQL_RESPONSE_PROJECTION_REQUIRED")
        manifest = parse(projection.manifest_bytes)
        if type(allow_incomplete) is not bool:
            raise StateError("ANALYSIS_INCOMPLETE_ACKNOWLEDGEMENT_INVALID")
        if manifest["completion"]["requiresIncompleteAcknowledgement"] and not allow_incomplete:
            raise StateError("ANALYSIS_ACKNOWLEDGE_INCOMPLETE_RESPONSE")
        manifest["completion"]["incompleteAcknowledged"] = allow_incomplete
        manifest_bytes = _json(manifest).encode()
        fields, source = manifest["projectedFields"], manifest["outputs"]["mapped.jsonl"]
        identity = {"schema": _FORMAT, "manifestSha256": digest(manifest_bytes),
                    "sourceBindingSha256": manifest["sourceBindingSha256"], "columns": list(zip(fields, fields))}
        dataset = {"kind": "retained-response", "name": manifest["name"], "rows": manifest["rows"],
                   "projectedFields": fields, "response": manifest["source"],
                   "completion": manifest["completion"], "mapping": manifest["mapping"],
                   "missingAsNull": manifest["missingAsNull"]}
        from .result import FileDelivery
        file = FileDelivery({"native": {"file": {**source, "path": str(projection.path)}}},
                            projection.path, 128 * 1024 * 1024)
        return self._import_rows(manifest_bytes=manifest_bytes, identity=identity, fields=fields,
            mapped=fields, total=manifest["rows"], source=source, opener=file.open,
            details={"dataset": dataset, "source_pages": None,
                     "row_representation": "explicit-response-projection",
                     "originalPaymentStatus": manifest["source"]["original"].get("paymentStatus")})

    def _import_rows(self, *, manifest_bytes, identity, fields, mapped, total, source, opener, details, semantics=None):
        """One original transaction and scalar/type policy for both native inputs."""
        version_id = digest(_json(identity).encode())
        table = "sf_dataset_rows_" + version_id
        quoted = [_identifier(column) for column in mapped]
        with self._connection() as db, opener() as stream:
            db.execute("BEGIN IMMEDIATE")
            try:
                existing = db.execute(f"SELECT version_id FROM {_META} WHERE version_id=?", (version_id,)).fetchone()
                if existing:
                    record = self._version(db, version_id)
                    db.commit()
                    return {**record, "import_status": "UNCHANGED"}
                # No declared type means no affinity conversion: numeric strings
                # and exact decimal text remain TEXT, while numbers remain numbers.
                db.execute(f"CREATE TABLE {_identifier(table)}({_identifier(_ORDINAL)} INTEGER PRIMARY KEY," + ",".join(quoted) + ")")
                insert = f"INSERT INTO {_identifier(table)} VALUES(" + ",".join("?" for _ in range(len(fields) + 1)) + ")"
                observed = [set() for _ in fields]
                checksum = hashlib.sha256()
                count = size = 0
                while raw := stream.readline(2_097_153):
                    if len(raw) > 2_097_152 or not raw.endswith(b"\n"):
                        raise StateError("DATASET_SQL_ROW_FORMAT_INVALID")
                    checksum.update(raw)
                    size += len(raw)
                    count += 1
                    if count > total or size > source["bytes"]:
                        raise StateError("DATASET_SQL_ROWS_CHANGED")
                    row = parse(raw)
                    if not isinstance(row, dict) or set(row) != set(fields):
                        raise StateError("DATASET_SQL_ROW_FIELDS_MISMATCH")
                    values = []
                    for index, field in enumerate(fields):
                        value, kind = _scalar(row[field])
                        values.append(value)
                        observed[index].add(kind)
                    db.execute(insert, (count, *values))
                if count != total or size != source["bytes"] or checksum.hexdigest() != source["sha256"]:
                    raise StateError("DATASET_SQL_ROWS_CHANGED")
                record = {**identity, "version_id": version_id, "table": table,
                          "created_at": datetime.now(timezone.utc).isoformat(), "row_count": count,
                          **details,
                          "jsonl": {key: source[key] for key in ("bytes", "sha256")},
                          "column_types": [{"source": field, "column": mapped[index], "json_types": sorted(observed[index])}
                                           for index, field in enumerate(fields)], "row_order_column": _ORDINAL}
                db.execute(f"INSERT INTO {_META}(version_id,created_at,record,manifest) VALUES(?,?,?,?)",
                           (version_id, record["created_at"], _json(record), manifest_bytes))
                if semantics is not None:
                    db.execute(f"INSERT INTO {_SEMANTICS}(version_id,document) VALUES(?,?)",
                               (version_id, semantics["bytes"]))
                record = self._version(db, version_id)
                db.commit()
                return {**record, "import_status": "IMPORTED"}
            except BaseException:
                db.rollback()
                raise

    def version(self, version_id):
        with self._connection(readonly=True) as db:
            return self._version(db, version_id)

    def manifest(self, version_id):
        """Read the exact original manifest retained with the acquired rows."""
        return parse(self.manifest_bytes(version_id))

    def manifest_bytes(self, version_id):
        """Return the original, hash-verified bytes without JSON re-encoding."""
        with self._connection(readonly=True) as db:
            row = db.execute(f"SELECT manifest,record FROM {_META} WHERE version_id=?", (version_id,)).fetchone()
            if row is None:
                raise StateError("DATASET_SQL_VERSION_NOT_FOUND")
            if digest(row["manifest"]) != parse(row["record"].encode())["manifestSha256"]:
                raise StateError("DATASET_SQL_RETAINED_MANIFEST_CHANGED")
            return bytes(row["manifest"])

    def semantics(self, version_id):
        """Original meanings plus reviewed source-to-SQL mapping, or None."""
        with self._connection(readonly=True) as db:
            db.execute("BEGIN")
            version = self._version(db, version_id)
            if version.get("semantics") is None:
                return None
            return {**version["semantics"], "version_id": version_id,
                    "document": version["semantic_dictionary"]}

    def semantics_bytes(self, version_id):
        """Return the exact retained dictionary file from this SQL edition."""
        with self._connection(readonly=True) as db:
            db.execute("BEGIN")
            version = self._version(db, version_id)
            if version.get("semantics") is None:
                return None
            row = db.execute(f"SELECT document FROM {_SEMANTICS} WHERE version_id=?", (version_id,)).fetchone()
            raw = bytes(row["document"])
            sql_context(raw, version["semantics"], version_id)
            return raw

    def compare_semantics(self, before_id, after_id):
        """Compare source meaning and SQL mapping separately from row changes."""
        with self._connection(readonly=True) as db:
            db.execute("BEGIN")
            before = self._version(db, before_id)
            after = self._version(db, after_id)
        first, second = before.get("semantics"), after.get("semantics")
        def columns(version):
            meanings = {column["name"]: column for column in version.get("semantic_dictionary", {}).get("columns", [])}
            return {column["source"]: {"sql_column": column["column"], "meaning": meanings.get(column["source"])}
                    for column in version.get("column_types", [])}
        left, right = columns(before), columns(after)
        changes = [{"source": name, "before": left.get(name), "after": right.get(name)}
                   for name in sorted(set(left) | set(right)) if left.get(name) != right.get(name)]
        return {"schema": "stellar-forge.python-semantic-comparison.v1",
                "before_version": before_id, "after_version": after_id,
                "before": first, "after": second,
                "definition_changed": (first or {}).get("definition_sha256") != (second or {}).get("definition_sha256"),
                "capture_changed": (first or {}).get("capture_manifest_sha256") != (second or {}).get("capture_manifest_sha256"),
                "mapping_changed": before.get("columns") != after.get("columns"),
                "columns": changes,
                "before_document": before.get("semantic_dictionary"),
                "after_document": after.get("semantic_dictionary")}

    def versions(self, *, before=None, limit=100):
        if type(limit) is not int or not 1 <= limit <= 1000 or before is not None and (type(before) is not int or before < 1):
            raise StateError("DATASET_SQL_HISTORY_PAGE_INVALID")
        with self._connection(readonly=True) as db:
            rows = db.execute(f"SELECT sequence,record FROM {_META} WHERE (? IS NULL OR sequence<?) ORDER BY sequence DESC LIMIT ?", (before, before, limit + 1)).fetchall()
            return {"versions": [{**parse(row["record"].encode()), "sequence": row["sequence"]} for row in rows[:limit]],
                    "next_before": rows[limit - 1]["sequence"] if len(rows) > limit else None}

    def current(self, name):
        with self._connection(readonly=True) as db:
            db.execute("BEGIN")
            row = db.execute(f"SELECT * FROM {_HEADS} WHERE name=?", (_view_name(name),)).fetchone()
            return {"name": name, "revision": 0, "version": None} if row is None else {"name": row["name"], "revision": row["revision"], "version": self._version(db, row["version_id"])}

    def activate(self, name, version_id, *, expected_revision):
        """Atomically select an imported version for one ordinary SQL view."""
        with self._connection() as db:
            db.execute("BEGIN IMMEDIATE")
            try:
                result = self._activate(db, name, version_id, expected_revision=expected_revision)
                db.commit()
                return result
            except BaseException:
                db.rollback()
                raise

    def _activate(self, db, name, version_id, *, expected_revision):
        """Apply the original view transition inside an owner's transaction.

        The analysis workspace uses this same operation to retain its reviewed
        comparison and select the candidate in one commit.
        """
        name = _view_name(name)
        if type(expected_revision) is not int or expected_revision < 0:
            raise StateError("DATASET_SQL_REVISION_REQUIRED")
        version = self._version(db, version_id)
        current = db.execute(f"SELECT * FROM {_HEADS} WHERE name=?", (name,)).fetchone()
        revision = current["revision"] if current else 0
        if revision != expected_revision:
            raise StateError("DATASET_SQL_VIEW_CHANGED")
        if current and current["version_id"] == version_id:
            return {"name": current["name"], "revision": revision, "version": version, "activation_status": "UNCHANGED"}
        if current:
            db.execute(f"DROP VIEW {_identifier(current['name'])}")
        elif db.execute("SELECT 1 FROM sqlite_master WHERE name=? COLLATE NOCASE", (name,)).fetchone():
            raise StateError("DATASET_SQL_VIEW_NAME_IN_USE")
        db.execute(f"CREATE VIEW {_identifier(name)} AS SELECT * FROM {_identifier(version['table'])}")
        db.execute(f"INSERT INTO {_HEADS}(name,version_id,revision) VALUES(?,?,?) ON CONFLICT(name) DO UPDATE SET version_id=excluded.version_id,revision=excluded.revision", (name, version_id, revision + 1))
        db.execute(f"INSERT INTO {_HISTORY}(name,version_id,previous_version,revision,activated_at) VALUES(?,?,?,?,?)",
                   (name, version_id, current["version_id"] if current else None, revision + 1, datetime.now(timezone.utc).isoformat()))
        return {"name": name, "revision": revision + 1, "version": version, "activation_status": "ACTIVATED"}

    def view_bindings(self):
        """Current named-view identities, suitable for a later query review."""
        with self._connection(readonly=True) as db:
            return self._views(db)

    @staticmethod
    def _views(db):
        return [dict(row) for row in db.execute(f"SELECT name,version_id,revision FROM {_HEADS} ORDER BY name COLLATE NOCASE")]

    def query(self, sql, parameters=(), *, max_rows=1000, max_result_bytes=16 * 1024 * 1024, timeout=10, expected_views=None):
        """Read-only SQL with result limits and the exact transaction's views.

        Pass a previously reviewed view_bindings() list to reject a changed
        analytical selection. The view snapshot and rows share one read
        transaction; immutable physical table names are also retained.
        """
        with self._connection(readonly=True) as db:
            db.execute("BEGIN")
            return self._query(db, sql, parameters, max_rows=max_rows,
                               max_result_bytes=max_result_bytes, timeout=timeout,
                               expected_views=expected_views)

    def _query(self, db, sql, parameters=(), *, max_rows=1000, max_result_bytes=16 * 1024 * 1024, timeout=10, expected_views=None):
        """Use the original SQL reader inside an already opened transaction."""
        if not db.in_transaction:
            raise StateError("DATASET_SQL_TRANSACTION_REQUIRED")
        if not isinstance(sql, str) or type(max_rows) is not int or not 1 <= max_rows <= 100_000 or type(max_result_bytes) is not int or not 1 <= max_result_bytes <= 256 * 1024 * 1024 or not isinstance(timeout, (int, float)) or not math.isfinite(timeout) or not 0 < timeout <= 300:
            raise StateError("DATASET_SQL_QUERY_OPTIONS_INVALID")
        from .query_stream import open_query, row_bytes
        try:
            with open_query(self, db, sql, parameters, timeout=timeout,
                            expected_views=expected_views) as stream:
                rows, size, truncated = [], 0, False
                for values in stream:
                    length = row_bytes(values)
                    if len(rows) == max_rows or size + length > max_result_bytes:
                        truncated = True
                        break
                    rows.append(values)
                    size += length
                return QueryResult(stream.columns, tuple(rows), truncated,
                                   tuple(stream.views), stream.read_tables)
        except StateError as exc:
            # Keep the existing preview/report error contract.
            if exc.code == "DATASET_SQL_QUERY_TIMEOUT":
                raise StateError("DATASET_SQL_QUERY_FAILED") from exc
            raise

    @contextmanager
    def stream_query(self, sql, parameters=(), *, timeout=300, expected_views=None, cancel=None):
        """Yield every row from one reviewed snapshot without materializing it.

        Use as a context manager so an early break closes the cursor and read
        transaction. cancel is an optional callable such as Event.is_set.
        """
        from .query_stream import open_query
        with self._connection(readonly=True) as db:
            db.execute("BEGIN")
            with open_query(self, db, sql, parameters, timeout=timeout,
                            expected_views=expected_views, cancel=cancel) as stream:
                yield stream

    def export_query(self, sql, parameters=(), *, destination, **options):
        """Write a complete private JSONL/CSV/SQLite result from the same reader."""
        from .query_export import export_query
        return export_query(self, sql, parameters, destination=destination, **options)

    def backup(self, destination):
        """Publish a consistent, create-only database copy that reopens normally."""
        folder = private_directory(Path(destination), create=True)
        target = folder / "datasets.sqlite3"
        if target.exists():
            raise StateError("DATASET_SQL_BACKUP_DESTINATION_EXISTS")
        fd, temporary = tempfile.mkstemp(prefix=".database-", dir=folder)
        os.close(fd)
        try:
            with self._connection(readonly=True) as source:
                copy = sqlite3.connect(temporary)
                try:
                    source.backup(copy)
                finally:
                    copy.close()
            with open(temporary, "rb") as stream:
                os.fsync(stream.fileno())
            os.link(temporary, target)
            sync_directory(folder)
        finally:
            os.unlink(temporary)
            sync_directory(folder)
        return target

"""Private local operation storage. No wallet keys or substitute payment ledger."""
from __future__ import annotations

from contextlib import contextmanager
import fcntl
import hashlib
import json
import os
from pathlib import Path
import stat
import tempfile

from .errors import StateError


def digest(raw: bytes) -> str:
    return hashlib.sha256(raw).hexdigest()


def unique_object(pairs):
    result = {}
    for key, value in pairs:
        if key in result:
            raise StateError("DUPLICATE_JSON_KEY")
        result[key] = value
    return result


def parse(raw: bytes):
    try:
        return json.loads(raw.decode("utf-8"), object_pairs_hook=unique_object,
                          parse_constant=lambda _: (_ for _ in ()).throw(ValueError()))
    except (ValueError, UnicodeError):
        raise StateError("INVALID_JSON") from None


def read(path: Path, limit: int) -> bytes:
    try:
        fd = os.open(path, os.O_RDONLY | os.O_NOFOLLOW)
        with os.fdopen(fd, "rb") as stream:
            info = os.fstat(stream.fileno())
            if not stat.S_ISREG(info.st_mode) or info.st_size > limit:
                raise StateError("FILE_LIMIT_OR_TYPE_INVALID")
            data = stream.read(limit + 1)
        if len(data) > limit:
            raise StateError("FILE_LIMIT_OR_TYPE_INVALID")
        return data
    except OSError:
        raise StateError("FILE_UNAVAILABLE") from None


def private_directory(path: Path, *, create=True) -> Path:
    path = path.expanduser().absolute()
    if create:
        path.mkdir(mode=0o700, parents=True, exist_ok=True)
    try:
        info = path.lstat()
        if not stat.S_ISDIR(info.st_mode) or info.st_mode & 0o077:
            raise StateError("PRIVATE_DIRECTORY_REQUIRED")
    except OSError:
        raise StateError("PRIVATE_DIRECTORY_REQUIRED") from None
    return path.resolve()


def sync_directory(path: Path):
    fd = os.open(path, os.O_RDONLY | os.O_DIRECTORY)
    try:
        os.fsync(fd)
    finally:
        os.close(fd)


def write(path: Path, data: bytes, *, exclusive=False):
    fd, name = tempfile.mkstemp(prefix=".write-", dir=path.parent)
    try:
        with os.fdopen(fd, "wb") as stream:
            stream.write(data)
            stream.flush()
            os.fsync(stream.fileno())
        if exclusive:
            # Publish a complete record without overwriting an existing one.
            # Readers cannot observe an empty/partial final result or attempt.
            os.link(name, path)
        else:
            os.replace(name, path)
        sync_directory(path.parent)
    finally:
        try:
            os.unlink(name)
        except FileNotFoundError:
            pass


def dump(path: Path, value, *, exclusive=False):
    write(path, (json.dumps(value, ensure_ascii=False, allow_nan=False, indent=2) + "\n").encode(),
          exclusive=exclusive)


@contextmanager
def lock(directory: Path):
    fd = os.open(directory / "operation.lock", os.O_RDWR | os.O_CREAT | os.O_NOFOLLOW, 0o600)
    try:
        try:
            fcntl.flock(fd, fcntl.LOCK_EX | fcntl.LOCK_NB)
        except BlockingIOError:
            raise StateError("OPERATION_BUSY") from None
        yield
    finally:
        os.close(fd)

"""Typed, reusable records from the original Node retained-response reader."""
from __future__ import annotations

from dataclasses import dataclass
import json
import os
from pathlib import Path
import shutil
import tempfile
from typing import Any, Iterator
from types import SimpleNamespace

from .errors import DeliveryError, StateError
from .storage import digest, lock, parse, private_directory, read, sync_directory, write

SCHEMA = "stellar-forge.python-stream-export.v1"
MAX_EXPORT_BYTES = 256 * 1024 * 1024


@dataclass(frozen=True)
class SSEEvent:
    index: int
    event: str
    data: str
    id: str
    retry: int | None = None

    def json(self) -> Any:
        """Parse application JSON explicitly; ordinary SSE data stays text."""
        return parse(self.data.encode("utf-8"))


@dataclass(frozen=True)
class NDJSONRecord:
    index: int
    value: Any


@dataclass(frozen=True)
class StreamDelivery:
    """The fully validated native record export; original raw bytes stay retained."""
    directory: Path
    manifest: dict

    @property
    def format(self):
        return self.manifest["format"]

    @property
    def complete(self):
        return self.manifest["complete"]

    @property
    def count(self):
        return self.manifest["records"]

    @property
    def source(self):
        return dict(self.manifest["source"])

    @property
    def file(self):
        from .result import FileDelivery
        metadata = {**self.manifest["file"], "path": str(self.directory / "records.jsonl")}
        return FileDelivery({"returncode": 0, "native": {"status": "FILE_SAVED", "file": metadata}},
                            Path(metadata["path"]), self.manifest["maxExportBytes"])

    def records(self, *, start=0) -> Iterator[SSEEvent | NDJSONRecord]:
        """Resume application consumption by original zero-based record index."""
        if type(start) is not int or not 0 <= start <= self.count:
            raise DeliveryError("STREAM_RECORD_INDEX_INVALID")
        # Reuse the existing Python file reader: it hashes the complete file
        # before exposing the same open descriptor, including when resuming.
        with self.file.open() as stream:
            index = 0
            maximum = self.manifest["maxExportBytes"]
            while raw := stream.readline(maximum + 1):
                if len(raw) > maximum or not raw.endswith(b"\n"):
                    raise DeliveryError("STREAM_EXPORT_RECORD_INVALID")
                value = parse(raw)
                if (not isinstance(value, dict) or value.get("format") != self.format
                        or type(value.get("index")) is not int or value["index"] != index):
                    raise DeliveryError("STREAM_EXPORT_RECORD_INVALID")
                if self.format == "sse":
                    if (not all(isinstance(value.get(key), str) for key in ("event", "data", "id"))
                            or ("retry" in value and (type(value["retry"]) is not int or value["retry"] < 0))):
                        raise DeliveryError("STREAM_EXPORT_RECORD_INVALID")
                    record = SSEEvent(index, value["event"], value["data"], value["id"], value.get("retry"))
                else:
                    if "value" not in value:
                        raise DeliveryError("STREAM_EXPORT_RECORD_INVALID")
                    record = NDJSONRecord(index, value["value"])
                if index >= start:
                    yield record
                index += 1
            if index != self.count:
                raise DeliveryError("STREAM_EXPORT_COUNT_CHANGED")

    def events(self, *, start=0) -> Iterator[SSEEvent]:
        if self.format != "sse":
            raise DeliveryError("RESPONSE_STREAM_FORMAT_MISMATCH")
        yield from self.records(start=start)

    def ndjson(self, *, start=0) -> Iterator[Any]:
        if self.format != "ndjson":
            raise DeliveryError("RESPONSE_STREAM_FORMAT_MISMATCH")
        for record in self.records(start=start):
            yield record.value


def _manifest(directory, fingerprint):
    result = parse(read(directory / "manifest.json", 1_048_576))
    if (not isinstance(result, dict) or result.get("schema") != SCHEMA
            or result.get("requestSha256") != fingerprint
            or result.get("format") not in ("sse", "ndjson")
            or type(result.get("complete")) is not bool
            or type(result.get("records")) is not int or result["records"] < 0
            or not isinstance(result.get("source"), dict)
            or not isinstance(result.get("file"), dict)
            or result["file"].get("path") != "records.jsonl"
            or type(result.get("maxExportBytes")) is not int
            or not 1 <= result["maxExportBytes"] <= 1_073_741_824):
        raise DeliveryError("STREAM_EXPORT_MANIFEST_INVALID")
    return StreamDelivery(directory, result)


def export_stream(result, *, format=None, allow_partial=False, max_record_bytes=None,
                  max_records=None, max_export_bytes=MAX_EXPORT_BYTES, cache_dir=None):
    runtime = result._runtime
    configuration = result._response_file
    if runtime is None or not isinstance(configuration, dict):
        raise StateError("ORIGINAL_STREAM_RUNTIME_REQUIRED")
    selected = configuration.get("stream") or result.delivery.get("stream") or {}
    format = selected.get("format") if format is None else format
    if format not in ("sse", "ndjson") or type(allow_partial) is not bool:
        raise DeliveryError("RESPONSE_STREAM_READ_OPTIONS_INVALID")
    if type(max_export_bytes) is not int or not 1 <= max_export_bytes <= 1_073_741_824:
        raise DeliveryError("STREAM_EXPORT_BYTE_LIMIT_INVALID")
    options = {"allowPartial": allow_partial}
    if max_record_bytes is not None:
        options["maxRecordBytes"] = max_record_bytes
    if max_records is not None:
        options["maxRecords"] = max_records
    payload = {"schema": "stellar-forge.python-stream-request.v1", "record": result.record,
               "responseFile": configuration, "format": format, "options": options,
               "maxExportBytes": max_export_bytes}
    raw = (json.dumps(payload, sort_keys=True, ensure_ascii=False, allow_nan=False,
                      separators=(",", ":")) + "\n").encode("utf-8")
    fingerprint = digest(raw)
    if cache_dir is None:
        if result._operation_directory is None:
            raise StateError("STREAM_EXPORT_DIRECTORY_REQUIRED")
        cache_dir = result._operation_directory / "stream-exports"
    root = private_directory(Path(cache_dir))
    destination = root / fingerprint
    with lock(root):
        if destination.exists():
            private_directory(destination, create=False)
            return _manifest(destination, fingerprint)
        temporary = Path(tempfile.mkdtemp(prefix=".stream-", dir=root))
        try:
            request = temporary / "source.json"
            write(request, raw, exclusive=True)
            native = runtime.checked(["export-stream", "--input", request, "--out", temporary],
                                     mode="ORIGINAL_PYTHON_STREAM_EXPORTED", target="consumer")
            saved = _manifest(temporary, fingerprint)
            if native != saved.manifest:
                raise DeliveryError("STREAM_EXPORT_RESULT_CHANGED")
            # Publish a complete directory only after the original reader's
            # framing and both source hash passes have finished successfully.
            os.rename(temporary, destination)
            sync_directory(root)
            return StreamDelivery(destination, saved.manifest)
        finally:
            if temporary.exists():
                shutil.rmtree(temporary)


def read_retained_response(*, checkout, config_file, result_file, cache_dir,
                           node="node", timeout=360):
    """Open an existing SF88 result for local consumption without buyer import.

    Accept the original CLI result or its existing Node/Python application
    envelope. This does not create an operation, approval or payment record.
    """
    from .result import BuyerResult
    from .runtime import Runtime
    config_raw = read(Path(config_file).expanduser().absolute(), 65536)
    result_raw = read(Path(result_file).expanduser().absolute(), 2_097_152)
    config, record = parse(config_raw), parse(result_raw)
    if not isinstance(config, dict) or not isinstance(record, dict):
        raise StateError("ORIGINAL_RETAINED_RESULT_REQUIRED")
    if record.get("mode") == "ORIGINAL_OPERATOR_APPROVED_BUYER_ATTEMPT":
        record = {"native": record}
    native = record.get("native")
    if (not isinstance(native, dict) or native.get("mode") != "ORIGINAL_OPERATOR_APPROVED_BUYER_ATTEMPT"
            or native.get("intentId") != config.get("operation", {}).get("intentId")):
        raise StateError("ORIGINAL_RETAINED_RESULT_REQUIRED")
    # Bind these original files into the export identity without changing them
    # or pretending a raw CLI result recorded a process exit code.
    if record.get("configSha256") is not None and record["configSha256"] != digest(config_raw):
        raise StateError("RESULT_CONFIG_MISMATCH")
    record = {**record, "retainedSourceFiles": {"configSha256": digest(config_raw),
                                              "resultSha256": digest(result_raw)}}
    response = config.get("responseFile")
    if not isinstance(response, dict) or not response.get("destination"):
        raise StateError("ORIGINAL_RESPONSE_FILE_REQUIRED")
    root = private_directory(Path(cache_dir))
    return BuyerResult(record, Path(response["destination"]), response.get("maxBytes", 67_108_864),
                       _runtime=Runtime(checkout, node=node, timeout=timeout),
                       _response_file={"maxBytes": 67_108_864, **response}, _operation_directory=root)


def export_saved_stream(*, checkout, response_file, saved, cache_dir, node="node", timeout=360, **options):
    """Consume an original SF31 writer receipt without creating a buyer attempt.

    ``response_file`` is the actual writer configuration. ``saved`` is its
    retained SAVED/FAILED responseFile view, including original stream metadata.
    The existing Node reader validates the full source hash and framed prefix.
    """
    from .runtime import Runtime
    if not isinstance(response_file, dict) or not isinstance(saved, dict):
        raise StateError("ORIGINAL_RESPONSE_FILE_REQUIRED")
    source = SimpleNamespace(
        record={"retainedSourceKind": "SF31_RESPONSE_FILE", "native": {"responseFile": saved}},
        delivery=saved, _response_file={"maxBytes": 67_108_864, **response_file},
        _runtime=Runtime(checkout, node=node, timeout=timeout),
        _operation_directory=private_directory(Path(cache_dir)),
    )
    return export_stream(source, **options)

