            await row.locator('[data-finding-disposition]').inputValue()===item.disposition&&
            await row.locator('[data-finding-reason]').inputValue()===item.dispositionReason,'CITATION_BROWSER_FINDING_DRAFT_RECOVERY_FAILED');
